// Expo config plugin: keep every CocoaPods target at the app's iOS deployment
// target, so the project builds with Xcode 27 (macOS 27 "Golden Gate").
//
// Xcode 27 rejects any target below iOS 15.0. react_native_post_install raises
// each pod's main target, but not its resource bundles — and three of ours
// still declare old minimums: SDWebImage (9.0), MapboxMapsResources (11.0),
// RNCAsyncStorage_resources (13.4). This adds a post_install step that raises
// anything below the app's target. Lives in a plugin (not a hand edit) because
// ios/ is regenerated by `expo prebuild`.

const fs = require('fs');
const path = require('path');
const { withDangerousMod } = require('@expo/config-plugins');
const { mergeContents } = require('@expo/config-plugins/build/utils/generateCode');

const SNIPPET = `    # Xcode 27 rejects iOS deployment targets below 15.0; some pod resource
    # bundles still declare 9.0-13.4. Raise every pod target to the app's.
    min_ios = podfile_properties['ios.deploymentTarget'] || '15.1'
    installer.pods_project.targets.each do |t|
      t.build_configurations.each do |c|
        v = c.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        c.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = min_ios if v && Gem::Version.new(v) < Gem::Version.new(min_ios)
      end
    end`;

function addPodTargetFix(podfile) {
  return mergeContents({
    tag: 'whim-xcode27-pod-targets',
    src: podfile,
    newSrc: SNIPPET,
    anchor: /post_install do \|installer\|/,
    offset: 1,
    comment: '#',
  }).contents;
}

const withXcode27PodTargets = (config) =>
  withDangerousMod(config, [
    'ios',
    async (cfg) => {
      const file = path.join(cfg.modRequest.platformProjectRoot, 'Podfile');
      fs.writeFileSync(file, addPodTargetFix(fs.readFileSync(file, 'utf8')));
      return cfg;
    },
  ]);

module.exports = withXcode27PodTargets;
module.exports.addPodTargetFix = addPodTargetFix;
